/**
 * Model for the enum editor table.
 */
class EnumTableModel : AbstractSortedTableModel<EnumEntry> {

	static int NAME_COL = 0;
	static int VALUE_COL = 1;
	static int COMMENT_COL = 2;

	static string NAME = "Name";
	static string VALUE = "Value";
	static string COMMENT = "Comment";
	private static string[] columnNames = new string[] { NAME, VALUE, COMMENT };

	private EnumDataType enuum;
	private List<EnumEntry> enumEntryList;

	private bool isChanged;
	private EnumEditorPanel editorPanel;

	EnumTableModel(EnumDataType enuum, EnumEditorPanel editorPanel) : base(VALUE_COL)
    {
		this.enuum = enuum;
		this.editorPanel = editorPanel;
		initialize();
	}

	/* @Override */
	public string getName() {
		return "Enum Editor";
	}

