		this.enuum = enuum;
		this.isChanged = isChanged;
		initialize();
	}

	int addEntry(int afterRow) {
		Long? value = findNextValue(afterRow);
		if (value == null) {
			return -1;
		}
		string name = getUniqueName();
		string comment = "";
		EnumEntry newEntry = new EnumEntry(name, value.Value, comment);
		try {
			enuum.add(name, value.Value, comment);
			int index = getIndexForRowObject(newEntry);
			if (index < 0) {
				index = -index - 1;
			}
			enumEntryList.add(newEntry);

			fireTableDataChanged();
			isChanged = true;
			return index;

		}
		catch (IllegalArgumentException e) {
			editorPanel.setStatusMessage(e.getMessage());
			return -1;
		}
	}

	private Long? findNextValue(int afterRow) {
		if (enumEntryList.isEmpty()) {
			return 0L;
		}
		if (afterRow < 0 || afterRow >= enumEntryList.size()) {
			afterRow = 0;
		}
		long min = enuum.getMinPossibleValue();
		long max = enuum.getMaxPossibleValue();
		long selected = enumEntryList.get(afterRow).getValue();
		long value = selected == max ? min : selected + 1;
		long start = value;
		while (enuum.getName(value) != null) {
			value = value == max ? min : value + 1;
			if (value == start) {
				return null;
			}
		}
		return value;
	}

	private string getUniqueName() {
		string name = "New_Name";
		int count = 0;
		while (enumContainsName(name)) {
			++count;
			name = "New_Name_(" + count + ")";
		}
		return name;
	}

	private void initialize() {
		enumEntryList = new();
		string[] names = enuum.getNames();
		foreach (string name in names) {
			enumEntryList.add(new EnumEntry(name, enuum.getValue(name), enuum.getComment(name)));
		}
		fireTableDataChanged();
	}

	private bool isNameValid(string name) {
		if (name == null || name.length() == 0) {
			editorPanel.setStatusMessage("Please enter a name");
			return false;
		}

		if (enumContainsName(name)) {
			editorPanel.setStatusMessage(name + " already exists");
			return false;
		}
		return true;
	}

	private bool enumContainsName(string name) {
		try {
			enuum.getValue(name);
			return true;
		}
		catch (NoSuchElementException e) {
			return false;
		}
	}

